using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.UI;using AstroGateway.CinematicHUD;
namespace AstroGateway.ProductionVisual {
 [Serializable]public class ControlTuning {public float deadZone=.14f,opacity=.32f,buttonScale=1;}
 [DefaultExecutionOrder(440)]public class ProductionPresentation:MonoBehaviour {
 public AstroGatewayHUDController hud;public ProductionModeCoordinator modes;public ControlTuning tuning=new ControlTuning();public float wheelRollDegrees;public string wheelSync="Measured travel / static suspension";public GameObject tuningWindow;float next;Transform[] wheels;Quaternion[] bases;Vector3 lastRover;bool wasPaused;Text modeLabel;const string Key="AstroGateway.ProductionVisual.ControlTuning.v1";
 void Start(){try{tuning=JsonUtility.FromJson<ControlTuning>(PlayerPrefs.GetString(Key,JsonUtility.ToJson(tuning)))??new ControlTuning();}catch{tuning=new ControlTuning();}hud.game.testSave=Path.Combine(Application.persistentDataPath,"AstroGateway_ProductionVisual_v1.json");wheels=hud.game.prototype.roverVisual.Cast<Transform>().Where(t=>t.name.StartsWith("Wheel_")).ToArray();bases=wheels.Select(t=>t.localRotation).ToArray();lastRover=hud.game.prototype.rover.transform.position;modeLabel=Label("Mode and camera",hud.safe,"",new Vector2(.40f,.83f),new Vector2(.60f,.875f),16);hud.Button("Production overview",hud.safe,"OVERVIEW / C",new Vector2(.39f,.875f),new Vector2(.49f,.91f),()=>modes.ToggleCinematic());hud.Button("Production chase",hud.safe,"CHASE DISTANCE",new Vector2(.50f,.875f),new Vector2(.61f,.91f),()=>{modes.cameraRig.nearChase=!modes.cameraRig.nearChase;});hud.Button("Production control tuning",hud.safe,"CONTROL TUNE",new Vector2(.62f,.875f),new Vector2(.73f,.91f),OpenTuning);ApplyLayout();}
 RectTransform Set(string name,Vector2 a,Vector2 b){var r=hud.safe.Find(name)as RectTransform;if(!r)return null;if(r.anchorMin!=a||r.anchorMax!=b){r.anchorMin=a;r.anchorMax=b;r.offsetMin=r.offsetMax=Vector2.zero;}return r;}
 public void ApplyLayout(){Set("Mission branding",new Vector2(.015f,.895f),new Vector2(.205f,.985f));Set("Survival resources",new Vector2(.22f,.91f),new Vector2(.80f,.985f));Set("Weather and clock",new Vector2(.82f,.89f),new Vector2(.985f,.985f));Set("Mission objectives",new Vector2(.015f,.65f),new Vector2(.205f,.87f));Set("Circular minimap panel",new Vector2(.84f,.62f),new Vector2(.95f,.85f));for(int i=0;i<4;i++)Set("Action "+i,new Vector2(.958f,.785f-i*.065f),new Vector2(.988f,.835f-i*.065f));Set("Rover telemetry",new Vector2(.35f,.025f),new Vector2(.65f,.115f));Set("Recent scientific scan",new Vector2(.76f,.22f),new Vector2(.985f,.35f));
 var safe=hud.safe.rect;float d=Mathf.Min(safe.width*.10f,safe.height*.19f),cx=hud.settings.leftHanded?.64f:.025f;float cy=.12f+d*hud.settings.joystickSize/(2*Mathf.Max(1,safe.height));Set("Analog movement joystick",new Vector2(cx,cy-d/2/safe.height),new Vector2(cx+d/safe.width,cy+d/2/safe.height));
 foreach(var pointer in hud.GetComponentsInChildren<HUDPointerControl>(true)){pointer.deadZone=Mathf.Clamp(tuning.deadZone,.05f,.3f);if(pointer.role=="move")pointer.GetComponent<Image>().color=new Color(.56f,.68f,.73f,Mathf.Clamp(tuning.opacity,.2f,.6f));}
 foreach(string name in new[]{"Scan","Context interact","Run or accelerate","Rover brake"}){var r=hud.safe.Find(name);if(r)r.localScale=Vector3.one*Mathf.Clamp(tuning.buttonScale,.8f,1.08f);}var branding=hud.safe.Find("Mission branding/Branding")?.GetComponent<Text>();if(branding)branding.fontSize=18;foreach(var text in hud.safe.Find("Survival resources").GetComponentsInChildren<Text>()){text.resizeTextForBestFit=true;text.resizeTextMinSize=12;text.resizeTextMaxSize=16;}}
 void Update(){if(tuningWindow&&UnityEngine.InputSystem.Keyboard.current?.escapeKey.wasPressedThisFrame==true)CloseTuning();else if(tuningWindow&&!hud.environment.paused)hud.environment.SetPaused(true);}
 void LateUpdate(){if(wheels==null)return;var p=hud.game.prototype;var now=p.rover.transform.position;var delta=now-lastRover;if(delta.magnitude<5)wheelRollDegrees=(wheelRollDegrees-Vector3.Dot(delta,p.rover.transform.forward)/.3744f*Mathf.Rad2Deg)%360;lastRover=now;for(int i=0;i<wheels.Length;i++)wheels[i].localRotation=bases[i]*Quaternion.AngleAxis(wheelRollDegrees,Vector3.up);
 if(Time.unscaledTime<next)return;next=Time.unscaledTime+.2f;ApplyLayout();modeLabel.gameObject.SetActive(hud.settings.visibility<3);modeLabel.text=modes.Current.ToString().ToUpperInvariant()+(modes.cinematic?" • C TO RETURN":"");foreach(string n in new[]{"Production overview","Production chase","Production control tuning"})hud.safe.Find(n).gameObject.SetActive(hud.settings.visibility<3);if(!p.driving)hud.roverReadout.text=$"SUITLINK • ASTRONAUT\nO2 {p.oxygen:F1}%   POWER {p.power:F1}%\nLOCAL SIMULATED TELEMETRY";}
 Text Label(string name,Transform parent,string content,Vector2 a,Vector2 b,int size){var g=new GameObject(name,typeof(RectTransform),typeof(Text));var r=(RectTransform)g.transform;r.SetParent(parent,false);r.anchorMin=a;r.anchorMax=b;r.offsetMin=r.offsetMax=Vector2.zero;var t=g.GetComponent<Text>();t.font=hud.theme.font;t.fontSize=size;t.color=hud.theme.text;t.text=content;t.raycastTarget=false;t.alignment=TextAnchor.MiddleCenter;return t;}
 public void OpenTuning(){if(tuningWindow)return;hud.CancelScan();wasPaused=hud.environment.paused;hud.environment.SetPaused(true);var g=new GameObject("Production control tuning modal",typeof(RectTransform),typeof(Image));var r=(RectTransform)g.transform;r.SetParent(hud.safe,false);r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=r.offsetMax=Vector2.zero;g.GetComponent<Image>().color=new Color(.01f,.015f,.025f,.94f);tuningWindow=g;Label("Tuning title",r,"NATIVE CONTROL TUNING • LOCAL PREFERENCES",new Vector2(.25f,.70f),new Vector2(.75f,.8f),24);Tuner("Dead zone",.58f,.05f,.3f,tuning.deadZone,v=>tuning.deadZone=v);Tuner("Control opacity",.46f,.2f,.6f,tuning.opacity,v=>tuning.opacity=v);Tuner("Button size",.34f,.8f,1.08f,tuning.buttonScale,v=>tuning.buttonScale=v);hud.Button("Close tuning",r,"APPLY / CLOSE",new Vector2(.40f,.2f),new Vector2(.6f,.28f),CloseTuning);}
 void Tuner(string name,float y,float min,float max,float value,Action<float> apply){Label(name,tuningWindow.transform,name,new Vector2(.25f,y),new Vector2(.43f,y+.06f),20);var g=new GameObject(name+" slider",typeof(RectTransform),typeof(Image),typeof(Slider));var r=(RectTransform)g.transform;r.SetParent(tuningWindow.transform,false);r.anchorMin=new Vector2(.45f,y);r.anchorMax=new Vector2(.74f,y+.06f);r.offsetMin=r.offsetMax=Vector2.zero;g.GetComponent<Image>().color=new Color(.2f,.25f,.3f,.8f);var handle=new GameObject("Handle",typeof(RectTransform),typeof(Image));var hr=(RectTransform)handle.transform;hr.SetParent(r,false);hr.anchorMin=Vector2.zero;hr.anchorMax=new Vector2(0,1);hr.sizeDelta=new Vector2(34,0);handle.GetComponent<Image>().color=hud.theme.orange;var s=g.GetComponent<Slider>();s.minValue=min;s.maxValue=max;s.value=value;s.handleRect=hr;s.targetGraphic=handle.GetComponent<Image>();s.onValueChanged.AddListener(v=>{apply(v);ApplyLayout();PlayerPrefs.SetString(Key,JsonUtility.ToJson(tuning));PlayerPrefs.Save();});}
 public void CloseTuning(){if(tuningWindow)Destroy(tuningWindow);tuningWindow=null;hud.environment.SetPaused(wasPaused);hud.ClearInput();}
 void OnDestroy(){if(tuningWindow&&hud)hud.environment.SetPaused(wasPaused);}
 }
}
